package com.agacostays.payment.service.impl;
import com.agacostays.payment.audit.*; import com.agacostays.payment.dto.request.RefundRequest; import com.agacostays.payment.dto.response.RefundResponse; import com.agacostays.payment.entity.*; import com.agacostays.payment.enums.*; import com.agacostays.payment.exception.*; import com.agacostays.payment.mapper.RefundMapper; import com.agacostays.payment.producer.PaymentEventProducer; import com.agacostays.payment.repository.*; import com.agacostays.payment.security.*; import com.agacostays.payment.service.*; import com.agacostays.payment.validation.PaymentValidationService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service @Transactional public class RefundServiceImpl implements RefundService { private final PaymentRepository payments; private final RefundRepository refunds; private final RefundMapper mapper; private final PaymentGatewayService gateway; private final PaymentValidationService validation; private final OwnerAccessValidator owner; private final CurrentUserProvider current; private final PaymentEventProducer events; private final PaymentAuditHelper audit; public RefundServiceImpl(PaymentRepository p,RefundRepository r,RefundMapper m,PaymentGatewayService g,PaymentValidationService v,OwnerAccessValidator o,CurrentUserProvider c,PaymentEventProducer e,PaymentAuditHelper a){payments=p;refunds=r;mapper=m;gateway=g;validation=v;owner=o;current=c;events=e;audit=a;} public RefundResponse refund(Long paymentId,RefundRequest req){Payment p=payments.findById(paymentId).orElseThrow(()->new ResourceNotFoundException("Payment not found: "+paymentId));if(!(current.hasRole("MANAGER")||current.hasRole("ROOT_ADMIN")||current.hasRole("SYSTEM")))throw new AccessDeniedException("Only manager/root admin/system can refund");validation.validateRefund(p,req.amount());var r=Refund.builder().paymentId(paymentId).amount(req.amount()).refundStatus(RefundStatus.PROCESSING).refundReason(req.reason()).createdAt(Instant.now()).build();r=refunds.save(r);try{String gid=gateway.createRefund(p.getGatewayPaymentId(),req.amount());r.setGatewayRefundId(gid);r.setRefundStatus(RefundStatus.PROCESSED);r.setProcessedAt(Instant.now());refunds.save(r);p.setPaymentStatus(req.amount().compareTo(p.getAmount())>=0?PaymentStatus.REFUNDED:PaymentStatus.PARTIALLY_REFUNDED);payments.save(p);events.refundProcessed(new com.agacostays.payment.event.RefundProcessedEvent("RefundProcessed",1,Instant.now(),r.getRefundId(),p.getPaymentId(),p.getCustomerId(),r.getAmount(),UUID.randomUUID().toString()));audit.log(new AuditLogRequest("PAYMENT_REFUNDED",current.userId(),p.getPaymentId(),"refund="+r.getRefundId()));return mapper.toResponse(r);}catch(Exception ex){r.setRefundStatus(RefundStatus.FAILED);refunds.save(r);events.refundFailed(new com.agacostays.payment.event.RefundFailedEvent("RefundFailed",1,Instant.now(),r.getRefundId(),p.getPaymentId(),p.getCustomerId(),r.getAmount(),ex.getMessage(),UUID.randomUUID().toString()));throw new BusinessRuleException("Refund processing failed");}}
 @Transactional(readOnly=true) public List<RefundResponse> refunds(Long paymentId){Payment p=payments.findById(paymentId).orElseThrow(()->new ResourceNotFoundException("Payment not found"));owner.validate(p);return this.refunds.findByPaymentIdOrderByCreatedAtDesc(paymentId).stream().map(mapper::toResponse).toList();}
 @Transactional(readOnly=true) public RefundResponse getRefund(Long refundId){Refund r=refunds.findById(refundId).orElseThrow(()->new ResourceNotFoundException("Refund not found"));Payment p=payments.findById(r.getPaymentId()).orElseThrow(()->new ResourceNotFoundException("Payment not found"));owner.validate(p);return mapper.toResponse(r);}}
